select 
from soap_consumables


        and name LIKE CONCAT('%', #{soapConsumables.name}, '%')


        and brand LIKE CONCAT('%', #{soapConsumables.brand}, '%')


        and consumable_type = #{soapConsumables.consumableType}


        and purchase_channel LIKE CONCAT('%', #{soapConsumables.purchaseChannel}, '%')


        and purchase_time >= #{soapConsumables.purchaseTime}


        and purchase_time <= #{soapConsumables.expiryDate}


        and status = #{soapConsumables.status}



limit #{pageable.offset}, #{pageable.pageSize}

select count(1)
from soap_consumables


        and name LIKE CONCAT('%', #{soapConsumables.name}, '%')


        and brand LIKE CONCAT('%', #{soapConsumables.brand}, '%')


        and consumable_type = #{soapConsumables.consumableType}


        and purchase_channel LIKE CONCAT('%', #{soapConsumables.purchaseChannel}, '%')


        and purchase_time >= #{purchaseTimeStart}


